def factorial(n: int) -> int:
    """Tính giai thừa của số nguyên không âm n bằng đệ quy."""
    if not isinstance(n, int) or n < 0:
        raise ValueError("n phải là số nguyên không âm.")
    if n in (0, 1):
        return 1
    return n * factorial(n - 1)

